 "content": "def transform(grid):
    """Expand a sparse diagonal color sequence into diagonal-periodic coloring.

    The input encodes a one-dimensional ordered cycle on successive diagonals;
    each output cell takes the encoded color at its diagonal phase.
    """
    h, w = len(grid), len(grid[0])
    # Collect palette cycle from left-to-right color changes along a diagonal
    # by scanning all nonzero cells in row-major order and retaining first
    # appearance. For stripe-row input, this is the stripe colors in order.
    colors = []
    for row in grid:
        for value in row:
            if value != 0 and value not in colors:
                colors.append(value)
    if not colors:
        return [row[:] for row in grid]
    # Repeating sequence is encoded by the first distinct color occurrences.
    return [[colors[(c-r) % len(colors)] for c in range(w)] for r in range(h)]
